UPDATE users
nickname = #{nickname}, birth_date = #{birthDate}, phone = #{phone}, gender = #{gender}, address = #{address}, updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{userId}

UPDATE users
   SET status          = 'INACTIVE'
     , deleted_at      = CURRENT_TIMESTAMP
     , email           = #{syntheticEmail}
     , withdrawn_email = #{withdrawnEmail}
     , updated_at      = CURRENT_TIMESTAMP
 WHERE user_id = #{userId}
   AND deleted_at IS NULL
